INSERT INTO `tbl_notices` (`id`, `title`, `content`, `category`, `meeting_type`, `meeting_date`, `priority`, `is_pinned`, `posted_by`, `posted_by_role`, `status`, `created_at`, `updated_at`) VALUES (1, 'Overhead Water Tank Deep Cleaning & Disinfection Schedule', 'Dear Residents,
INSERT INTO `tbl_notices` (`id`, `title`, `content`, `category`, `meeting_type`, `meeting_date`, `priority`, `is_pinned`, `posted_by`, `posted_by_role`, `status`, `created_at`, `updated_at`) VALUES (2, 'Notification: 18th Annual General Meeting (AGM 2026)', 'Notice is hereby given that the 18th Annual General Meeting (AGM) of South Dumdum Enclave Residents\' Association will be held on Sunday, September 14, at 6:30 PM at the Community Hall (Ground Floor).
